"use client"

import * as React from "react"
import { Menubar as MenubarPrimitive } from "radix-ui"

import { useInk, useInkSeed, useMergedRef } from "@/lib/ink/react"
import {
  dropdownMenuContentRecipe,
  dropdownMenuItemRecipe,
} from "@/lib/ink/recipes/dropdown-menu-ink"
import { menubarRootRecipe, menubarTriggerRecipe } from "@/lib/ink/recipes/menubar-ink"
import { cn } from "@/lib/utils"

function Menubar({ className, ref, children, ...props }: React.ComponentProps<typeof MenubarPrimitive.Root>) {
  const { hostRef, hostProps, node } = useInk({
    recipe: menubarRootRecipe,
    params: {},
    kind: "menubar",
    still: true,
  })

  return (
    <MenubarPrimitive.Root
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      data-slot="menubar"
      className={cn("relative isolate flex h-10 items-center gap-1 rounded-[var(--radius-md)] p-1", className)}
      {...props}
    >
      {node}
      <div className="relative z-[1] flex items-center gap-1">{children}</div>
    </MenubarPrimitive.Root>
  )
}

function MenubarMenu(props: React.ComponentProps<typeof MenubarPrimitive.Menu>) {
  return <MenubarPrimitive.Menu data-slot="menubar-menu" {...props} />
}

function MenubarGroup(props: React.ComponentProps<typeof MenubarPrimitive.Group>) {
  return <MenubarPrimitive.Group data-slot="menubar-group" {...props} />
}

function MenubarPortal(props: React.ComponentProps<typeof MenubarPrimitive.Portal>) {
  return <MenubarPrimitive.Portal data-slot="menubar-portal" {...props} />
}

function MenubarTrigger({
  className,
  ref,
  children,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Trigger>) {
  const { hostRef, hostProps, node } = useInk({
    recipe: menubarTriggerRecipe,
    params: {},
    kind: "menu-trigger",
    still: true,
  })

  return (
    <MenubarPrimitive.Trigger
      ref={useMergedRef<HTMLButtonElement>(hostRef, ref)}
      {...hostProps}
      data-slot="menubar-trigger"
      className={cn(
        "relative isolate flex cursor-default select-none items-center rounded-[var(--radius-sm)] px-3 py-1.5 text-sm font-medium outline-none",
        "text-muted-foreground focus:text-foreground data-[state=open]:text-foreground",
        className,
      )}
      {...props}
    >
      {node}
      <span className="relative z-[1]">{children}</span>
    </MenubarPrimitive.Trigger>
  )
}

function MenubarContentPanel({
  seed,
  children,
}: {
  seed?: string | number
  children: React.ReactNode
}) {
  const { hostRef, hostProps, node } = useInk({
    recipe: dropdownMenuContentRecipe,
    params: {},
    kind: "dropdown-menu",
    seed,
    still: true,
  })
  return (
    <div
      ref={hostRef}
      {...hostProps}
      className="relative isolate overflow-hidden rounded-[var(--radius-md)] p-1 shadow-[0_10px_32px_-8px_rgb(var(--sd-shade)/0.2)]"
    >
      {node}
      <div className="relative z-[1]">{children}</div>
    </div>
  )
}

function MenubarContent({
  className,
  align = "start",
  alignOffset = -4,
  sideOffset = 8,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Content> & { seed?: string | number }) {
  return (
    <MenubarPortal>
      <MenubarPrimitive.Content
        ref={ref}
        data-slot="menubar-content"
        align={align}
        alignOffset={alignOffset}
        sideOffset={sideOffset}
        className={cn(
          "z-50 min-w-[12rem] overflow-hidden outline-none",
          "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
          "data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
          className,
        )}
        {...props}
      >
        <MenubarContentPanel seed={seed}>{children}</MenubarContentPanel>
      </MenubarPrimitive.Content>
    </MenubarPortal>
  )
}

function MenubarSub(props: React.ComponentProps<typeof MenubarPrimitive.Sub>) {
  return <MenubarPrimitive.Sub data-slot="menubar-sub" {...props} />
}

function MenubarSubTrigger({
  className,
  inset,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.SubTrigger> & { inset?: boolean }) {
  return (
    <MenubarPrimitive.SubTrigger
      ref={ref}
      data-slot="menubar-sub-trigger"
      className={cn(
        "flex cursor-default select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none",
        "focus:bg-[color-mix(in_srgb,var(--sd-rose-wash)_40%,transparent)] data-[state=open]:bg-[color-mix(in_srgb,var(--sd-rose-wash)_40%,transparent)]",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      <span className="ms-auto text-xs opacity-60" aria-hidden>
        ›
      </span>
    </MenubarPrimitive.SubTrigger>
  )
}

function MenubarSubContent({
  className,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.SubContent> & { seed?: string | number }) {
  return (
    <MenubarPrimitive.SubContent
      ref={ref}
      data-slot="menubar-sub-content"
      className={cn(
        "z-50 min-w-[8rem] overflow-hidden outline-none",
        "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
        "data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
        className,
      )}
      {...props}
    >
      <MenubarContentPanel seed={seed}>{children}</MenubarContentPanel>
    </MenubarPrimitive.SubContent>
  )
}

function MenubarItem({
  className,
  inset,
  disabled,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Item> & {
  inset?: boolean
  seed?: string | number
}) {
  const itemSeed = useInkSeed(seed)
  const { hostRef, hostProps, node } = useInk({
    recipe: dropdownMenuItemRecipe,
    params: { disabled: !!disabled },
    kind: "menu-item",
    seed: itemSeed,
    still: true,
  })

  return (
    <MenubarPrimitive.Item
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      data-slot="menubar-item"
      disabled={disabled}
      className={cn(
        "relative isolate flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none",
        "text-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {node}
      <span className="relative z-[1]">{children}</span>
    </MenubarPrimitive.Item>
  )
}

function MenubarCheckboxItem({
  className,
  children,
  checked,
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.CheckboxItem>) {
  return (
    <MenubarPrimitive.CheckboxItem
      ref={ref}
      data-slot="menubar-checkbox-item"
      className={cn(
        "relative flex cursor-default select-none items-center rounded-sm py-1.5 ps-8 pe-2 text-sm outline-none",
        "focus:bg-[color-mix(in_srgb,var(--sd-rose-wash)_42%,transparent)]",
        "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      checked={checked}
      {...props}
    >
      <MenubarPrimitive.ItemIndicator className="absolute start-2 inline-flex size-3.5 items-center justify-center">
        ✓
      </MenubarPrimitive.ItemIndicator>
      {children}
    </MenubarPrimitive.CheckboxItem>
  )
}

function MenubarRadioGroup(props: React.ComponentProps<typeof MenubarPrimitive.RadioGroup>) {
  return <MenubarPrimitive.RadioGroup data-slot="menubar-radio-group" {...props} />
}

function MenubarRadioItem({
  className,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.RadioItem>) {
  return (
    <MenubarPrimitive.RadioItem
      ref={ref}
      data-slot="menubar-radio-item"
      className={cn(
        "relative flex cursor-default select-none items-center rounded-sm py-1.5 ps-8 pe-2 text-sm outline-none",
        "focus:bg-[color-mix(in_srgb,var(--sd-rose-wash)_42%,transparent)]",
        "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <MenubarPrimitive.ItemIndicator className="absolute start-2 inline-flex size-3.5 items-center justify-center">
        ●
      </MenubarPrimitive.ItemIndicator>
      {children}
    </MenubarPrimitive.RadioItem>
  )
}

function MenubarLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Label> & { inset?: boolean }) {
  return (
    <MenubarPrimitive.Label
      data-slot="menubar-label"
      className={cn("px-2 py-1.5 text-xs font-medium text-muted-foreground", inset && "ps-8", className)}
      {...props}
    />
  )
}

function MenubarSeparator({ className, ...props }: React.ComponentProps<typeof MenubarPrimitive.Separator>) {
  return (
    <MenubarPrimitive.Separator
      data-slot="menubar-separator"
      className={cn("-mx-1 my-1 h-px bg-[color-mix(in_srgb,var(--sd-line-soft)_80%,transparent)]", className)}
      {...props}
    />
  )
}

function MenubarShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="menubar-shortcut"
      className={cn("ms-auto text-xs tracking-widest text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Menubar,
  MenubarCheckboxItem,
  MenubarContent,
  MenubarGroup,
  MenubarItem,
  MenubarLabel,
  MenubarMenu,
  MenubarPortal,
  MenubarRadioGroup,
  MenubarRadioItem,
  MenubarSeparator,
  MenubarShortcut,
  MenubarSub,
  MenubarSubContent,
  MenubarSubTrigger,
  MenubarTrigger,
}

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box, focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export const menubarRootRecipe = defineRecipe<Record<string, never>>({
  id: 'menubar-root',
  kind: 'menubar',
  layers: ['rest'],
  pad: 6,
  draw(ink, { w, h }) {
    const r = clamp(Math.min(w, h) * 0.14, 4, 8)
    const inset = 0.5
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)
    ink.part('fill', () => {
      softFill(ink, body, [
        { color: 'sand-slip', alpha: 0.72, wobble: 0.45 },
        { color: 'sand-shade', alpha: 0.18, inset: 0.8, wobble: 0.5 },
      ])
    })
    box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
      pen: 'pencil.fine',
      corner: r,
      loose: 0.9,
      opts: { alpha: 0.42, wobble: 0.35, simple: w > 320 },
    })
  },
})

export const menubarTriggerRecipe = defineRecipe<Record<string, never>>({
  id: 'menubar-trigger',
  kind: 'menu-trigger',
  layers: ['rest', 'hover', 'open', 'focus'],
  lazy: ['focus'],
  pad: 4,
  draw(ink, { w, h }, _params, ctx) {
    const r = clamp(Math.min(w, h) * 0.18, 3, 5)
    const body = roundRectPoly(0.5, 0.5, w - 1, h - 1, r)

    ctx.lazy('focus', (fink) => {
      wash(fink, body, 'star', { alpha: 0.12, material: 'wash', wobble: 0.45 })
      focusRing(fink, 0, 0, w, h, { r, pen: 'horizonPencil.fine', opts: { alpha: 0.72, simple: true } })
    })
    if (ctx.lazyOnly) return

    ink.layer('hover', () => {
      wash(ink, body, 'rose-wash', { alpha: 0.4, material: 'wash', wobble: 0.75 })
    })

    ink.layer('open', () => {
      wash(ink, body, 'rose-wash', { alpha: 0.52, material: 'wash', wobble: 0.8 })
      wash(ink, body, 'horizon', { alpha: 0.14, material: 'wash', inset: 0.35 })
    })
  },
})

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { drawCompactSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const dropdownMenuContentRecipe = defineRecipe<Record<string, never>>({
  id: 'dropdown-menu-content',
  kind: 'dropdown-menu',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }) {
    ink.layer('rest', () => drawCompactSandSlipPanel(ink, w, h))
  },
})

export interface DropdownMenuItemParams {
  disabled?: boolean
}

export const dropdownMenuItemRecipe = defineRecipe<DropdownMenuItemParams>({
  id: 'dropdown-menu-item',
  kind: 'menu-item',
  layers: ['rest', 'hover', 'focus', 'disabled'],
  lazy: ['focus'],
  pad: 4,
  draw(ink, { w, h }, { disabled }, ctx) {
    const r = clamp(Math.min(w, h) * 0.2, 2, 4)
    const body = roundRectPoly(0.5, 0.5, w - 1, h - 1, r)

    if (disabled) {
      if (ctx.lazyOnly) return
      ink.layer('disabled', () => {
        wash(ink, body, 'sand-shade', { alpha: 0.2, material: 'wash', wobble: 0.35 })
      })
      return
    }

    ctx.lazy('focus', (fink) => {
      wash(fink, body, 'rose-wash', { alpha: 0.38, material: 'wash', wobble: 0.65 })
      focusRing(fink, 0, 0, w, h, { r, pen: 'horizonPencil.fine', opts: { alpha: 0.7, simple: true } })
    })
    if (ctx.lazyOnly) return

    ink.layer('hover', () => {
      wash(ink, body, 'rose-wash', { alpha: 0.42, material: 'wash', wobble: 0.72 })
    })
  },
})

import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type PanelTone = 'default' | 'lifted'

/** Compact sand-slip panel (Tooltip / Toast). */
export function drawCompactSandSlipPanel(ink: Ink, w: number, h: number) {
  const r = clamp(Math.min(w, h) * 0.1, 4, 7)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.82, wobble: 0.48 },
      { color: 'sand', alpha: 0.28, inset: 0.9, wobble: 0.55 },
      { color: 'wash-gold', alpha: 0.06, inset: 1.6, wobble: 0.9 },
    ])
  })
  box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
    pen: 'pencil.fine',
    corner: r,
    loose: 0.95,
    opts: { alpha: 0.48, wobble: 0.38, simple: w > 280 },
  })
  box(ink, 1.1, 1.1, w - 2.2, h - 2.2, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1,
    opts: { alpha: 0.18, wobble: 0.42, simple: true, color: 'line-soft' },
  })
}

/** Sand-slip panel fill + double loose border (Card / Dialog / Popover). */
export function drawSandSlipPanel(ink: Ink, w: number, h: number, tone: PanelTone = 'default') {
  const r = clamp(Math.min(w, h) * 0.04, 5, 12)
  const inset = 0.7
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: tone === 'lifted' ? 0.9 : 0.78, wobble: 0.5 },
      { color: 'sand', alpha: 0.32, inset: 1.2, wobble: 0.65 },
      { color: 'wash-gold', alpha: 0.08, inset: 2.4, wobble: 1.1 },
    ])
  })
  box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
    pen: 'pencil.fine',
    corner: r,
    loose: 1.15,
    opts: { alpha: 0.52, wobble: 0.42, simple: w > 420 },
  })
  box(ink, 1.4, 1.4, w - 2.8, h - 2.8, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1.25,
    opts: { alpha: 0.22, wobble: 0.5, simple: true, color: 'line-soft' },
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
